export function getPathById(id: string): LearningPath | undefined {
  return PREDEFINED_PATHS.find((p) => p.id === id);
}

// Generate a custom path based on a user-entered goal
export function generateCustomPath(goal: string, timePerDay: number, level: string): LearningPath {
  const id = 'custom-' + goal.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 30);
  const estimatedDays = Math.round(60 * (timePerDay / 30));
  
  return {
    id,
    title: goal.charAt(0).toUpperCase() + goal.slice(1),
    emoji: '🎯',
    category: 'Custom Path',
    description: `Your personalized learning path to ${goal}.`,
    gradient: 'from-primary-500 to-primary-700',
    defaultDays: estimatedDays,
    experience: level as 'Beginner' | 'Intermediate' | 'Advanced',
    milestones: [
      { id: `${id}-m1`, title: 'Foundations', subtitle: 'Build core knowledge', icon: '🟢', color: 'emerald', estimatedDays: Math.round(estimatedDays * 0.2), skills: ['Fundamentals', 'Key concepts', 'Terminology'], missionCount: 5, missionIds: [], projectIds: [] },
      { id: `${id}-m2`, title: 'Core Skills', subtitle: 'Develop essential abilities', icon: '🔵', color: 'blue', estimatedDays: Math.round(estimatedDays * 0.25), skills: ['Core skills', 'Practice', 'Technique'], missionCount: 5, missionIds: [], projectIds: [] },
      { id: `${id}-m3`, title: 'Practice & Application', subtitle: 'Apply what you learned', icon: '🟣', color: 'purple', estimatedDays: Math.round(estimatedDays * 0.25), skills: ['Real-world practice', 'Problem solving'], missionCount: 5, missionIds: [], projectIds: [] },
      { id: `${id}-m4`, title: 'Advanced Projects', subtitle: 'Build and create', icon: '🟠', color: 'orange', estimatedDays: Math.round(estimatedDays * 0.2), skills: ['Projects', 'Portfolio'], missionCount: 4, missionIds: [], projectIds: [] },
      { id: `${id}-m5`, title: 'Final Challenge', subtitle: 'Showcase your mastery', icon: '🏆', color: 'amber', estimatedDays: Math.round(estimatedDays * 0.1), skills: ['Mastery', 'Showcase'], missionCount: 3, missionIds: [], projectIds: [] },
    ],
    missions: [],
    projects: [],
    challenges: [],
  };
}
